const allItems = $input.all();
const results = [];

for (const item of allItems) {
  const input = item.json;

  let body = '';

  if (typeof input.text === 'string') {
    body = input.text;
  } else if (typeof input.snippet === 'string') {
    body = input.snippet;
  } else if (typeof input.html === 'string') {
    body = input.html.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
  }

  if (!body && input.payload) {
    if (input.payload.body && input.payload.body.data) {
      try {
        body = Buffer.from(input.payload.body.data, 'base64').toString('utf-8');
      } catch (e) {}
    }
    if (!body && Array.isArray(input.payload.parts)) {
      for (const part of input.payload.parts) {
        if (part.body && part.body.data) {
          try {
            const decoded = Buffer.from(part.body.data, 'base64').toString('utf-8');
            if (part.mimeType === 'text/plain') {
              body = decoded;
              break;
            } else if (part.mimeType === 'text/html' && !body) {
              body = decoded.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
            }
          } catch (e) {}
        }
      }
    }
    // Handle nested multipart structure (alternative type)
    if (!body && Array.isArray(input.payload.parts)) {
      for (const part of input.payload.parts) {
        if (Array.isArray(part.parts)) {
          for (const subpart of part.parts) {
            if (subpart.body && subpart.body.data) {
              try {
                const decoded = Buffer.from(subpart.body.data, 'base64').toString('utf-8');
                if (subpart.mimeType === 'text/plain') {
                  body = decoded;
                  break;
                } else if (subpart.mimeType === 'text/html' && !body) {
                  body = decoded.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
                }
              } catch (e) {}
            }
          }
        }
      }
    }
  }

  if (!body) body = input.snippet || 'No body found';

  // Decode common HTML entities
  body = body
    .replace(/&#39;/g, "'")
    .replace(/&apos;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&nbsp;/g, ' ')
    .replace(/&ndash;/g, '–')
    .replace(/&mdash;/g, '—');

  body = body.substring(0, 6000);

  const source = body.includes('seek.com') ? 'Seek' :
                 body.includes('indeed.com') ? 'Indeed' :
                 body.includes('linkedin.com') ? 'LinkedIn' : 'Email';

  results.push({
    json: {
      ad_text: body,
      source: source,
      source_email_id: input.id || '',
      source_subject: input.Subject || input.subject || '',
      received_at: new Date().toISOString()
    }
  });
}

return results;

const item = $input.item.json;
const prompt = `You are parsing an Australian job-alert digest email. The email contains MULTIPLE separate job postings as a list. Your job: identify each individual job and extract its core fields plus the source URL.
The source of this digest is: ${item.source}
Return ONLY a JSON object with this exact structure:
{
  "jobs": [
    {
      "role_title": "string",
      "company": "string or null",
      "location": "string",
      "salary_snippet": "string or null (whatever pay info is visible in the digest)",
      "url": "string or null (the URL to the full job ad if visible)"
    }
  ]
}
Rules:
- Each individual job listing must become one object in the jobs array.
- Skip headers, footers, unsubscribe links, marketing text, navigation links.
- A typical entry has: title line, company line, location line, optional salary line, optional logo marker.
- DO NOT merge multiple jobs together. Each role gets its own entry.
- If a digest has 15 jobs, return 15 entries. If it has 3, return 3.
- For url: extract any job-specific URL near each entry. Seek URLs contain "seek.com.au/job/" or similar. Indeed URLs contain "indeed.com/viewjob". LinkedIn URLs contain "linkedin.com/jobs/view/". If no URL is findable for that specific job, return null.
DIGEST EMAIL TEXT:
${item.ad_text}`;

return [{
  json: {
    ...item,
    anthropic_model: "claude-haiku-4-5",
    anthropic_max_tokens: 4096,
    anthropic_prompt: prompt
  }
}];

const response = $input.item.json;
const upstream = $('Build Split Prompt').first().json;

// Anthropic API returns content array
const content = response.content?.[0]?.text || '';

let parsed = { jobs: [] };
try {
  // Strip markdown fences if present
  const cleaned = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  return [{ json: { error: 'Failed to parse split response', raw: content.substring(0, 500) } }];
}

const jobs = parsed.jobs || [];
const results = [];
for (const job of jobs) {
  results.push({
    json: {
      role_title: job.role_title || 'Unknown',
      company: job.company || null,
      location: job.location || 'Unknown',
      salary_snippet: job.salary_snippet || null,
      url: job.url || null,
      source: upstream.source,
      source_email_id: upstream.source_email_id,
      received_at: upstream.received_at,
      ad_text_full: upstream.ad_text
    }
  });
}
return results;

const response = $input.item.json;
const upstream = $('Build Quick Score Prompt').item.json;
const content = response.content?.[0]?.text || '';

// Defaults if parse fails
let score = {
  entity_type: 'unknown',
  entity_confidence: 1,
  technical_fit_score: 1,
  salary_value_score: 1,
  commercial_outreach_score: 1,
  total: 3,
  score_band: 'ignore',
  reasoning_flags: [],
  reason: 'parse failed'
};

try {
  const cleaned = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  const parsed = JSON.parse(cleaned);

  // Clamp / coerce each field to expected type
  score.entity_type = parsed.entity_type || 'unknown';
  score.entity_confidence = Math.min(5, Math.max(1, parseInt(parsed.entity_confidence) || 1));
  score.technical_fit_score = Math.min(5, Math.max(1, parseInt(parsed.technical_fit_score) || 1));
  score.salary_value_score = Math.min(5, Math.max(1, parseInt(parsed.salary_value_score) || 1));
  score.commercial_outreach_score = Math.min(5, Math.max(1, parseInt(parsed.commercial_outreach_score) || 1));
  score.total = Math.min(15, Math.max(3, parseInt(parsed.total) ||
    (score.technical_fit_score + score.salary_value_score + score.commercial_outreach_score)));
// Validate score_band strictly — only accept valid enum values, else derive from total
const validBands = ['critical', 'hot', 'warm', 'low', 'ignore'];
const aiBand = (parsed.score_band || '').toLowerCase().trim();
score.score_band = validBands.includes(aiBand) ? aiBand : (
  score.total >= 13 ? 'critical' :
  score.total >= 10 ? 'hot' :
  score.total >= 7  ? 'warm' :
  score.total >= 4  ? 'low' : 'ignore'
);

// Also validate entity_type strictly
const validEntityTypes = ['direct_employer', 'recruiter_agency', 'msp_rpo', 'job_board_aggregator', 'unknown'];
const aiEntity = (parsed.entity_type || '').toLowerCase().trim();
score.entity_type = validEntityTypes.includes(aiEntity) ? aiEntity : 'unknown';
  score.reasoning_flags = Array.isArray(parsed.reasoning_flags) ? parsed.reasoning_flags : [];
  score.reason = parsed.reason || '';
} catch (e) {
  // Leave defaults; reason already says 'parse failed'
}

// Generate stable per-job ID
const idSeed = `${upstream.role_title}|${upstream.company || ''}|${upstream.url || ''}`;
let hash = 0;
for (let i = 0; i < idSeed.length; i++) {
  hash = ((hash << 5) - hash) + idSeed.charCodeAt(i);
  hash = hash & hash;
}
const jobId = 'J-' + Math.abs(hash).toString(36).toUpperCase().padStart(8, '0').substring(0, 8);

return {
  json: {
    job_id: jobId,
    role_title: upstream.role_title,
    company: upstream.company,
    location: upstream.location,
    salary_snippet: upstream.salary_snippet,
    url: upstream.url,
    source: upstream.source,
    source_email_id: upstream.source_email_id,
    received_at: upstream.received_at,
    quick_score: score.total,
    score_band: score.score_band,
    entity_type: score.entity_type,
    entity_confidence: score.entity_confidence,
    technical_fit_score: score.technical_fit_score,
    salary_value_score: score.salary_value_score,
    commercial_outreach_score: score.commercial_outreach_score,
    reasoning_flags: score.reasoning_flags,
    quick_score_reason: score.reason
  }
};

