const item = $input.item.json;
let url = item.url || '';

// Rewrite Indeed click-tracking URLs to canonical viewjob URL
if (url.includes('indeed.com/rc/clk') || url.includes('indeed.com/pagead/clk')) {
  const jkMatch = url.match(/[?&]jk=([a-f0-9]+)/);
  if (jkMatch) {
    url = `https://au.indeed.com/viewjob?jk=${jkMatch[1]}`;
  }
}

return {
  json: {
    ...item,
    url: url
  }
};

const response = $input.item.json;
const upstream = $('Parse Quick Score').item.json;
const content = response.content?.[0]?.text || '';

let extracted = {};
try {
  const cleaned = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  extracted = JSON.parse(cleaned);
} catch (e) {
  extracted = { error: 'parse failed' };
}

// Coerce / clamp ints
function clampInt(v, min, max) {
  if (v === null || v === undefined || v === '') return null;
  const n = parseInt(v);
  if (isNaN(n)) return null;
  return Math.min(max, Math.max(min, n));
}

function intOrNull(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = parseInt(v);
  return isNaN(n) ? null : n;
}

// Merge reasoning flags from both stages
const baseFlags = Array.isArray(upstream.reasoning_flags) ? upstream.reasoning_flags : [];
const addFlags = Array.isArray(extracted.additional_flags) ? extracted.additional_flags : [];
const allFlags = Array.from(new Set([...baseFlags, ...addFlags]));

return {
  json: {
    job_id: upstream.job_id,
    role_title: upstream.role_title,
    company: upstream.company,
    location: upstream.location,
    salary_snippet: upstream.salary_snippet,
