    commercial_outreach_score: upstream.commercial_outreach_score,
    quick_score_reason: upstream.quick_score_reason,
    fetched_ok: upstream.fetched_ok,

    // From deep extract
    full_description: extracted.full_description || '',
    key_requirements: Array.isArray(extracted.key_requirements) ? extracted.key_requirements.join('; ') : '',
    nice_to_haves: Array.isArray(extracted.nice_to_haves) ? extracted.nice_to_haves.join('; ') : '',
    company_blurb: extracted.company_blurb || '',
    company_size_hint: extracted.company_size_hint || 'unknown',
    hiring_contact_name: extracted.hiring_contact_name || '',
    hiring_contact_email: extracted.hiring_contact_email || '',
    fifo: extracted.fifo || 'unclear',
    contract_type: extracted.contract_type || 'unclear',
    salary_clarified: extracted.salary_clarified || upstream.salary_snippet || '',
    salary_min: intOrNull(extracted.salary_min),
    salary_max: intOrNull(extracted.salary_max),
    inferred_client_name: extracted.inferred_client_name || '',
    inferred_client_confidence: clampInt(extracted.inferred_client_confidence, 1, 5),
    pain_hypothesis: extracted.pain_hypothesis || '',
    outreach_angle: extracted.outreach_angle || '',
    recommended_service: extracted.recommended_service || 'unknown',
    recommended_first_action: extracted.recommended_first_action || '',
    employee_instruction: extracted.employee_instruction || '',
    urgency: extracted.urgency || 'unclear',
