const item = $input.item.json;

// Parse location into city/state. Format: "Bangalow, NSW" or "Sydney NSW"
function parseLocation(loc) {
  if (!loc) return { city: null, state: null };
  loc = loc.trim();
  if (loc.toLowerCase() === 'unknown') return { city: null, state: null };

  const auStates = ['WA', 'NSW', 'VIC', 'QLD', 'SA', 'TAS', 'ACT', 'NT'];
  const parts = loc.split(/\s+/);
  let state = null;
  let cityPart = loc;

  const lastWord = parts[parts.length - 1].replace(/[,]/g, '').toUpperCase();
  if (auStates.includes(lastWord)) {
    state = lastWord;
    cityPart = parts.slice(0, -1).join(' ').replace(/,$/, '').trim();
  }

  if (cityPart.includes(',')) {
    cityPart = cityPart.split(',').pop().trim();
  }

  return { city: cityPart || null, state };
}

const loc = parseLocation(item.location);

// Normalise source to lowercase enum
const sourceMap = { 'indeed': 'indeed', 'seek': 'seek', 'linkedin': 'linkedin', 'email': 'gmail' };
const source = sourceMap[(item.source || '').toLowerCase()] || 'other';

// Build raw_payload for audit
const rawPayload = {
  job_id: item.job_id,
  source_email_id: item.source_email_id,
  received_at: item.received_at,
  quick_score_reason: item.quick_score_reason,
  full_description: item.full_description,
  key_requirements: item.key_requirements,
  nice_to_haves: item.nice_to_haves,
  company_blurb: item.company_blurb,
  company_size_hint: item.company_size_hint,
  fifo: item.fifo,
  contract_type: item.contract_type,
  salary_clarified: item.salary_clarified,
  fetched_ok: item.fetched_ok
};

return {
  json: {
    role_title: item.role_title || '(Untitled Role)',
    company_name: item.company || '(Unknown Company)',
    location_city: loc.city,
    location_state: loc.state,
    external_source: source,
    external_url: item.url,
    discipline: item.full_description ? item.full_description.substring(0, 200) : null,
    salary_text: item.salary_clarified || item.salary_snippet || null,
    salary_min: item.salary_min,
    salary_max: item.salary_max,
    ai_score: item.quick_score,
    ai_score_reasoning: item.quick_score_reason,
    score_band: item.score_band,
    entity_type: item.entity_type,
    entity_confidence: item.entity_confidence,
    technical_fit_score: item.technical_fit_score,
    salary_value_score: item.salary_value_score,
    commercial_outreach_score: item.commercial_outreach_score,
    pain_hypothesis: item.pain_hypothesis,
    outreach_angle: item.outreach_angle,
    inferred_client_name: item.inferred_client_name || null,
    inferred_client_confidence: item.inferred_client_confidence,
    recommended_service: item.recommended_service,
    recommended_first_action: item.recommended_first_action,
    employee_instruction: item.employee_instruction,
    relationship_potential: item.relationship_potential,
    placement_probability: item.placement_probability,
    commercial_viability: item.commercial_viability,
    reasoning_flags: JSON.stringify(item.reasoning_flags || []),
    hiring_contact_name: item.hiring_contact_name || null,
    hiring_contact_email: item.hiring_contact_email || null,
    discovered_at: item.received_at,
    raw_payload: JSON.stringify(rawPayload),
    // pass-through for downstream Telegram message
